create table agency_sms_settings(tenant_id varchar(100) primary key references tenants(id),enabled boolean not null default false,daily_limit integer not null check(daily_limit between 1 and 1000),version bigint not null default 1,reason text not null,updated_by varchar(100) not null,updated_at timestamptz not null default now());
create table agency_sms_contacts(tenant_id varchar(100) not null references tenants(id),user_id varchar(100) not null,phone_cipher text not null,masked_phone varchar(32) not null,consented boolean not null,version bigint not null,verified_by varchar(100) not null,reason text not null,updated_at timestamptz not null default now(),primary key(tenant_id,user_id));
create table agency_sms_outbox(id varchar(100) primary key,tenant_id varchar(100) not null references tenants(id),package_id varchar(100) not null,reminder_id varchar(100) not null,recipient_id varchar(100) not null,contact_version bigint not null,status varchar(20) not null check(status in ('queued','sending','accepted','delivered','failed','unknown','cancelled')),provider_ref varchar(200),attempts integer not null default 0,error_text text not null default '',created_by varchar(100) not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(tenant_id,reminder_id));
create index agency_sms_pending on agency_sms_outbox(status,created_at);
create table agency_sms_attempts(id varchar(100) primary key,tenant_id varchar(100) not null,outbox_id varchar(100) not null references agency_sms_outbox(id),attempt integer not null,status varchar(20) not null,note text not null,created_at timestamptz not null default now());
create table agency_sms_receipts(tenant_id varchar(100) not null,outbox_id varchar(100) not null references agency_sms_outbox(id),receipt_hash char(64) not null,status varchar(20) not null,created_at timestamptz not null default now(),primary key(tenant_id,outbox_id,receipt_hash));
create table agency_sms_quota(tenant_id varchar(100) not null,quota_day date not null,used integer not null check(used>0),primary key(tenant_id,quota_day));
